import React, { useEffect, useState } from 'react';
import axios from 'axios';
import '../../styles/ManageUsers.css';

const ManageUsers = () => {
  const [users, setUsers] = useState([]);
  const [formData, setFormData] = useState({ name: '', email: '', role: '', password: '' }); // Добавил password для создания
  const [message, setMessage] = useState('');
  const [editingUser, setEditingUser] = useState(null);
  const [isCreating, setIsCreating] = useState(false); // Новый режим создания

  const fetchUsers = async () => {
    try {
      const res = await axios.get('/api/users', { withCredentials: true });
      setUsers(res.data);
    } catch (err) {
      console.error(err);
      setMessage('Ошибка загрузки пользователей');
    }
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const handleDelete = async (id) => {
    if (!window.confirm('Удалить пользователя?')) return;
    try {
      await axios.delete(`/api/users/${id}`, { withCredentials: true });
      setMessage('Пользователь удалён');
      fetchUsers();
    } catch (err) {
      setMessage('Ошибка при удалении');
    }
  };

  const handleEditClick = (users) => {
    setEditingUser(users._id);
    setIsCreating(false);
    setFormData({ name: users.name, email: users.email, role: users.role, password: '' });
    setMessage('');
  };

  const handleCancel = () => {
    setEditingUser(null);
    setIsCreating(false);
    setFormData({ name: '', email: '', role: '', password: '' });
    setMessage('');
  };

  const handleChange = (e) => {
    setFormData(prev => ({ ...prev, [e.target.name]: e.target.value }));
  };

  // Обновление пользователя
  const handleUpdate = async (e) => {
    e.preventDefault();
    try {
      await axios.put(`/api/users/${editingUser}`, formData, { withCredentials: true });
      setMessage('Пользователь обновлён');
      setEditingUser(null);
      setFormData({ name: '', email: '', role: '', password: '' });
      fetchUsers();
    } catch (err) {
      setMessage(err.response?.data?.error || 'Ошибка при обновлении');
    }
  };

  // Создать нового пользователя (только админ)
router.post('/', authMiddleware, checkAdmin, async (req, res) => {
  try {
    const { name, email, password, role } = req.body;

    if (!name || !email || !password || !role) {
      return res.status(400).json({ error: 'Все поля обязательны' });
    }

    const existingUser = await User.findOne({ email });
    if (existingUser) {
      return res.status(400).json({ error: 'Пользователь с таким email уже существует' });
    }

    const salt = await bcrypt.genSalt(10);
    const passwordHash = await bcrypt.hash(password, salt);

    const newUser = new User({ name, email, passwordHash, role });
    await newUser.save();

    res.status(201).json({ message: 'Пользователь создан', user: { _id: newUser._id, name, email, role } });
  } catch (err) {
    console.error('Ошибка сервера:', err); // Добавь вывод ошибки в консоль
    res.status(500).json({ error: 'Ошибка сервера при создании пользователя' });
  }
});
};

